const body = $json.body ?? $json;

const projectId = String(
  body.projectId ??
  body.project_id ??
  body.id ??
  'default'
);

const batchSizeRaw = Number(body.batchSize ?? body.batch_size ?? 40);
const batchSize = Math.max(10, Math.min(60, Number.isFinite(batchSizeRaw) ? batchSizeRaw : 40));

let rawAds =
  body.ads ??
  body.candidates ??
  body.records ??
  [];

if (!Array.isArray(rawAds)) rawAds = [rawAds];

if (!rawAds.length) {
  throw new Error('MR04 requires body.ads[] (or candidates[] / records[]).');
}

const projectContext =
  body.projectContext ??
  body.relevanceContext ??
  body.context ??
  {
    projectName: body.projectName ?? body.project_name ?? null,
    brief: body.brief ?? null,
    seedPlans:
      body.queryPlan?.seedPlans ??
      body.seedPlans ??
      body.plan?.seedPlans ??
      []
  };

function cleanText(value, max = 1600) {
  if (value === null || value === undefined) return '';
  let s = String(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (s.length > max) s = s.slice(0, max);
  return s;
}

function getBody(ad) {
  const bodyCandidate =
    ad.adContent ??
    ad.ad_content ??
    ad.ad_body_text ??
    ad.adText ??
    ad.ad_text ??
    ad.body ??
    ad.snapshot?.body?.text ??
    ad.snapshot?.body?.markup ??
    '';
  return cleanText(bodyCandidate, 1800);
}

function getTitle(ad) {
  return cleanText(
    ad.adTitle ??
    ad.ad_title ??
    ad.headline ??
    ad.title ??
    ad.snapshot?.title ??
    '',
    350
  );
}

function getDescription(ad) {
  return cleanText(
    ad.adLinkDescription ??
    ad.ad_link_description ??
    ad.link_description ??
    ad.description ??
    ad.snapshot?.link_description ??
    '',
    500
  );
}

function getPageName(ad) {
  return cleanText(
    ad.pageName ??
    ad.page_name ??
    ad.brand_name ??
    ad.snapshot?.page_name ??
    '',
    250
  );
}

function getLinkUrl(ad) {
  return cleanText(
    ad.adLinkUrl ??
    ad.ad_link_url ??
    ad.link_url ??
    ad.cta_url ??
    ad.snapshot?.link_url ??
    '',
    700
  );
}

function getId(ad) {
  const value =
    ad.adArchiveId ??
    ad.ad_archive_id ??
    ad.externalAdId ??
    ad.external_ad_id ??
    ad.metaAdId ??
    ad.meta_ad_id ??
    ad.id;
  return value === null || value === undefined ? '' : String(value).trim();
}

function getMatch(ad) {
  return {
    queryText: cleanText(
      ad.queryText ??
      ad.query_text ??
      ad.sourceQuery ??
      ad.source_query ??
      ad.query ??
      '',
      200
    ),
    queryType: cleanText(ad.queryType ?? ad.query_type ?? '', 50),
    seedText: cleanText(ad.seedText ?? ad.seed_text ?? '', 350),
    concept: cleanText(ad.concept ?? ad.seedConcept ?? ad.seed_concept ?? '', 250)
  };
}

const byId = new Map();

for (const ad of rawAds) {
  if (!ad || typeof ad !== 'object') continue;

  const adArchiveId = getId(ad);
  if (!adArchiveId) continue;

  const match = getMatch(ad);

  if (!byId.has(adArchiveId)) {
    byId.set(adArchiveId, {
      adArchiveId,
      localId: String(ad.localId ?? ad.local_id ?? ad.rowId ?? ad.row_id ?? ''),
      pageName: getPageName(ad),
      body: getBody(ad),
      title: getTitle(ad),
      description: getDescription(ad),
      linkUrl: getLinkUrl(ad),
      startDate: ad.startDate ?? ad.start_date ?? ad.ad_delivery_start_time ?? null,
      endDate: ad.endDate ?? ad.end_date ?? ad.ad_delivery_stop_time ?? null,
      isActive: ad.isActive ?? ad.is_active ?? null,
      matches: [match]
    });
  } else {
    const existing = byId.get(adArchiveId);
    const key = JSON.stringify(match);
    if (!existing.matches.some(m => JSON.stringify(m) === key) && existing.matches.length < 8) {
      existing.matches.push(match);
    }
    if (!existing.body) existing.body = getBody(ad);
    if (!existing.title) existing.title = getTitle(ad);
    if (!existing.pageName) existing.pageName = getPageName(ad);
    if (!existing.description) existing.description = getDescription(ad);
    if (!existing.linkUrl) existing.linkUrl = getLinkUrl(ad);
  }
}

const ads = [...byId.values()];

if (!ads.length) {
  throw new Error('MR04 did not find any usable ad ID. Every ad must have ad_archive_id/adArchiveId/external_ad_id/id.');
}

return [{
  json: {
    projectId,
    filterVersion: 'mr04-ad-relevance-v1',
    batchSize,
    projectContext,
    ads
  }
}];

const source = $json;
const ads = Array.isArray(source.ads) ? source.ads : [];
const batchSize = source.batchSize ?? 40;
const totalBatches = Math.ceil(ads.length / batchSize);

const result = [];

for (let i = 0; i < totalBatches; i++) {
  result.push({
    json: {
      projectId: source.projectId,
      filterVersion: source.filterVersion,
      batchIndex: i,
      totalBatches,
      projectContext: source.projectContext,
      ads: ads.slice(i * batchSize, (i + 1) * batchSize)
    }
  });
}

return result;

