const outputs = $input.all();
const sourceBatches = $('Create Batches').all();

const expected = new Map();
for (const item of sourceBatches) {
  const ads = Array.isArray(item.json.ads) ? item.json.ads : [];
  for (const ad of ads) {
    expected.set(String(ad.adArchiveId), ad);
  }
}

const allowedDecision = new Set(['KEEP', 'REJECT', 'REVIEW']);
const allowedReason = new Set([
  'IN_SCOPE',
  'ADJACENT_IN_SCOPE',
  'OUT_OF_SCOPE_TOPIC',
  'ACCIDENTAL_KEYWORD_MATCH',
  'NON_MARKET_NOISE',
  'INSUFFICIENT_DATA',
  'AMBIGUOUS'
]);

const decisionsById = new Map();

for (const item of outputs) {
  const payload = item.json.output ?? item.json;
  const decisions = Array.isArray(payload.decisions) ? payload.decisions : [];

  for (const d of decisions) {
    const id = String(d.adArchiveId ?? '').trim();
    if (!id || !expected.has(id) || decisionsById.has(id)) continue;

    let decision = String(d.decision ?? 'REVIEW').toUpperCase();
    if (!allowedDecision.has(decision)) decision = 'REVIEW';

    let confidence = Number(d.confidence);
    if (!Number.isFinite(confidence)) confidence = 0;
    confidence = Math.max(0, Math.min(100, Math.round(confidence)));

    let reasonCode = String(d.reasonCode ?? 'AMBIGUOUS').toUpperCase();
    if (!allowedReason.has(reasonCode)) reasonCode = 'AMBIGUOUS';

    // Bezpiecznik: niespójne powody nie mogą prowadzić do automatycznego odrzutu.
    if (
      decision === 'REJECT' &&
      !['OUT_OF_SCOPE_TOPIC', 'ACCIDENTAL_KEYWORD_MATCH', 'NON_MARKET_NOISE'].includes(reasonCode)
    ) {
      decision = 'REVIEW';
      reasonCode = 'AMBIGUOUS';
      confidence = Math.min(confidence, 50);
    }

    if (
      decision === 'KEEP' &&
      !['IN_SCOPE', 'ADJACENT_IN_SCOPE'].includes(reasonCode)
    ) {
      decision = 'REVIEW';
      reasonCode = 'AMBIGUOUS';
      confidence = Math.min(confidence, 50);
    }

    decisionsById.set(id, {
      adArchiveId: id,
      decision,
      confidence,
      reasonCode,
      reason: String(d.reason ?? '').replace(/\s+/g, ' ').trim().slice(0, 400)
    });
  }
}

// Nigdy nie odrzucamy reklamy tylko dlatego, że model pominął ją w odpowiedzi.
for (const id of expected.keys()) {
  if (!decisionsById.has(id)) {
    decisionsById.set(id, {
      adArchiveId: id,
      decision: 'REVIEW',
      confidence: 0,
      reasonCode: 'INSUFFICIENT_DATA',
      reason: 'Brak kompletnej decyzji modelu; wymagana weryfikacja.'
    });
  }
}

const decisions = [...decisionsById.values()];

const summary = {
  total: decisions.length,
  keep: decisions.filter(d => d.decision === 'KEEP').length,
  reject: decisions.filter(d => d.decision === 'REJECT').length,
  review: decisions.filter(d => d.decision === 'REVIEW').length
};

const firstBatch = sourceBatches[0]?.json ?? {};

return [{
  json: {
    ok: true,
    projectId: String(firstBatch.projectId ?? 'default'),
    filterVersion: String(firstBatch.filterVersion ?? 'mr04-ad-relevance-v1'),
    processedAt: new Date().toISOString(),
    summary,
    decisions
  }
}];
